public static class PlaceSleigh167 {public static string Main(){const string D="Assets/Events/NewYear/Models/";AssetDatabase.Refresh();var importer=(ModelImporter)AssetImporter.GetAtPath(D+"SleighThief.fbx");importer.globalScale=1;importer.useFileScale=true;importer.bakeAxisConversion=true;importer.importAnimation=false;importer.importCameras=false;importer.importLights=false;importer.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;importer.SaveAndReimport();
var colors=new Dictionary<string,string>{{"Skin_Green","86A447"},{"Skin_Dark","4C6630"},{"Holiday_Red","B8323D"},{"Warm_Cream","F4E6CA"},{"Runner_Gold","DFA92E"},{"Ice_Blue","86DDF4"},{"Charcoal","343441"},{"Wood_Brown","76503A"}};var mats=new Dictionary<string,Material>();foreach(var kv in colors){var path=D+kv.Key+".mat";if(AssetDatabase.LoadAssetAtPath<Material>(path)!=null){mats[kv.Key]=AssetDatabase.LoadAssetAtPath<Material>(path);continue;}var m=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/Events/NewYear/Snow.mat"));m.name=kv.Key;ColorUtility.TryParseHtmlString("#"+kv.Value,out var col);m.color=col;AssetDatabase.CreateAsset(m,path);mats[kv.Key]=m;}
var scene=SceneManager.GetSceneByPath("Assets/Scenes/LevelEvent.unity");if(!scene.isLoaded)scene=EditorSceneManager.OpenScene("Assets/Scenes/LevelEvent.unity",OpenSceneMode.Additive);var previous=scene.GetRootGameObjects().FirstOrDefault(g=>g.name=="SleighThief_VisualPreview");if(previous!=null)UnityEngine.Object.DestroyImmediate(previous);
var model=AssetDatabase.LoadAssetAtPath<GameObject>(D+"SleighThief.fbx");var root=new GameObject("SleighThief_VisualPreview");SceneManager.MoveGameObjectToScene(root,scene);var v=(GameObject)PrefabUtility.InstantiatePrefab(model,root.transform);v.name="VisualRoot";
foreach(var r in root.GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select(m=>mats.TryGetValue(m.name.Replace(" (Instance)",""),out var mm)?mm:throw new Exception("Unknown material "+m.name)).ToArray();}
var front=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Hull_Front");var rear=root.GetComponentsInChildren<Transform>().First(t=>t.name=="Hull_Rear");var delta=front.position-rear.position;if(delta.z<0||Mathf.Abs(delta.y)>.2f)throw new Exception("FBX axis mismatch "+delta);
foreach(var name in new[]{"DriverAnchor","DropAnchor","AimAnchor","VfxAnchor"}){var g=new GameObject(name);g.transform.SetParent(root.transform,false);g.transform.localPosition=name=="DropAnchor"?new Vector3(0,-.5f,-1.7f):new Vector3(0,1.8f,0);}
var prefab=PrefabUtility.SaveAsPrefabAsset(root,D+"SleighThief_Visual.prefab");var board=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<BoardController>(true)).FirstOrDefault();var origin=board!=null?board.transform.position:Vector3.zero;root.transform.position=origin+new Vector3(9,4,10);root.transform.rotation=Quaternion.Euler(0,210,0);
var b=root.GetComponentsInChildren<Renderer>()[0].bounds;foreach(var r in root.GetComponentsInChildren<Renderer>())b.Encapsulate(r.bounds);var tris=root.GetComponentsInChildren<MeshFilter>().Sum(m=>m.sharedMesh.triangles.Length/3);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();var sv=SceneView.lastActiveSceneView;if(sv!=null){sv.LookAt(b.center,Quaternion.Euler(25,35,0),10);sv.Focus();}
var report="FBX forward="+delta+"; root scale="+v.transform.localScale+"; renderers="+root.GetComponentsInChildren<Renderer>().Length+"; triangles="+tris+"; bounds="+b.size+"; position="+root.transform.position+"; board="+origin+"; missingScripts="+root.GetComponentsInChildren<Transform>(true).Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));File.WriteAllText("Docs/locations/previews/sleigh-thief167-verification.txt",report);return report;}}